        <div style={{ padding: sidebarCollapsed ? "20px 0" : "20px", borderBottom: "1px solid rgba(212,168,85,0.15)", display: "flex", alignItems: "center", justifyContent: sidebarCollapsed ? "center" : "space-between" }}>
