        </footer>
      </div>

      {/* ── MODALS ── */}
      {showAuth && <AuthModal onClose={() => setShowAuth(false)} onLogin={setUser} />}
      {showCart && <CartModal cartItems={cartItems} onClose={() => setShowCart(false)} onUpdateQty={updateQty} onRemove={removeItem} />}
    </div>
  );
