        </div>
        <span className="text-[10px] uppercase tracking-[0.16em] font-black text-[#0F766E] block mb-1">
          {category}
        </span>
        {productName && (
          <h4 className="font-bold text-sm text-[#111827] truncate max-w-full">
            {productName}
          </h4>
        )}
      </div>
    );
  }

  return (
    <img
      src={imgSrc}
      alt={alt}
      onError={handleError}
      loading="lazy"
      decoding="async"
