/**
 * Async thunk to fetch products with pagination
 */
export const fetchProducts = createAsyncThunk(
  'products/fetchProducts',
  async (params = {}, { rejectWithValue }) => {
    try {
      const response = await productService.getProducts(params);
      return response.data;
    } catch (error) {
      return rejectWithValue(error.response?.data?.message || 'Failed to fetch products');
    }
  }
);

/**
 * Async thunk to fetch a single product
 */
export const fetchProductById = createAsyncThunk(
  'products/fetchProductById',
  async (id, { rejectWithValue }) => {
    try {
      const response = await productService.getProductById(id);
      return response.data;
    } catch (error) {
      return rejectWithValue(error.response?.data?.message || 'Failed to fetch product');
    }
  }
);

/**
 * Async thunk to search products
 */
export const searchProducts = createAsyncThunk(
  'products/searchProducts',
  async ({ query, params = {} }, { rejectWithValue }) => {
    try {
      const response = await productService.searchProducts(query, params);
      return response.data;
    } catch (error) {
      return rejectWithValue(error.response?.data?.message || 'Search failed');
    }
  }
);

/**
 * Async thunk to filter products
 */
export const filterProducts = createAsyncThunk(
  'products/filterProducts',
  async (filters = {}, { rejectWithValue }) => {
    try {
      const response = await productService.filterProducts(filters);
      return response.data;
    } catch (error) {
      return rejectWithValue(error.response?.data?.message || 'Filter failed');
    }
  }
);

const initialState = {
  products: [],
  selectedProduct: null,
  loading: false,
  error: null,
  pagination: {
    page: 0,
    size: 12,
    totalElements: 0,
    totalPages: 0,
    last: true,
  },
  filters: {
    categoryId: null,
    minPrice: null,
    maxPrice: null,
    fabric: null,
    sortBy: 'createdAt',
    sortDir: 'desc',
  },
  searchQuery: '',
};

const productSlice = createSlice({
  name: 'products',
  initialState,
  reducers: {
    setFilters: (state, action) => {
      state.filters = { ...state.filters, ...action.payload };
    },
    clearFilters: (state) => {
      state.filters = initialState.filters;
    },
    setSearchQuery: (state, action) => {
      state.searchQuery = action.payload;
    },
    clearSelectedProduct: (state) => {
      state.selectedProduct = null;
    },
    clearError: (state) => {
      state.error = null;
    },
  },
  extraReducers: (builder) => {
    builder
      // Fetch products
      .addCase(fetchProducts.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchProducts.fulfilled, (state, action) => {
        state.loading = false;
        const fetched = action.payload?.content || [];
        state.products = fetched.length > 0 ? fetched : MOCK_PRODUCTS;
        state.pagination = {
          page: action.payload?.page || 0,
          size: action.payload?.size || 12,
          totalElements: fetched.length > 0 ? (action.payload?.totalElements || 0) : MOCK_PRODUCTS.length,
          totalPages: fetched.length > 0 ? (action.payload?.totalPages || 0) : 1,
          last: fetched.length > 0 ? (action.payload?.last ?? true) : true,
        };
      })
      .addCase(fetchProducts.rejected, (state, action) => {
        state.loading = false;
        state.products = MOCK_PRODUCTS;
        state.pagination = {
          page: 0,
          size: 12,
          totalElements: MOCK_PRODUCTS.length,
          totalPages: 1,
          last: true,
        };
        state.error = null;
      })
      // Fetch product by ID
      .addCase(fetchProductById.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchProductById.fulfilled, (state, action) => {
        state.loading = false;
        state.selectedProduct = action.payload || null;
      })
      .addCase(fetchProductById.rejected, (state, action) => {
        state.loading = false;
        const id = action.meta.arg;
        const mockProd = MOCK_PRODUCTS.find(p => p.id === Number(id));
        if (mockProd) {
          state.selectedProduct = mockProd;
          state.error = null;
        } else {
          state.error = action.payload;
        }
      })
      // Search products
      .addCase(searchProducts.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(searchProducts.fulfilled, (state, action) => {
        state.loading = false;
        const fetched = action.payload?.content || [];
        state.products = fetched.length > 0 ? fetched : MOCK_PRODUCTS.filter(p => 
          p.name.toLowerCase().includes(state.searchQuery.toLowerCase())
        );
        state.pagination = {
          page: action.payload?.page || 0,
          size: action.payload?.size || 12,
          totalElements: fetched.length > 0 ? (action.payload?.totalElements || 0) : state.products.length,
          totalPages: fetched.length > 0 ? (action.payload?.totalPages || 0) : 1,
          last: true,
        };
      })
      .addCase(searchProducts.rejected, (state, action) => {
        state.loading = false;
        state.products = MOCK_PRODUCTS.filter(p => 
          p.name.toLowerCase().includes(state.searchQuery.toLowerCase())
        );
        state.pagination = {
          page: 0,
          size: 12,
          totalElements: state.products.length,
          totalPages: 1,
          last: true,
        };
        state.error = null;
      })
      // Filter products
      .addCase(filterProducts.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(filterProducts.fulfilled, (state, action) => {
        state.loading = false;
        const fetched = action.payload?.content || [];

        if (fetched.length > 0) {
          state.products = fetched;
          state.pagination = {
            page: action.payload?.page || 0,
            size: action.payload?.size || 12,
            totalElements: action.payload?.totalElements || 0,
            totalPages: action.payload?.totalPages || 0,
            last: action.payload?.last ?? true,
          };
        } else {
          const { minPrice, maxPrice, fabric, categoryId, categoryName } = action.meta.arg || {};
          let filtered = MOCK_PRODUCTS;
          if (categoryName) {
            filtered = filtered.filter(p => p.categoryName?.toLowerCase().includes(categoryName.toLowerCase()));
          } else if (categoryId) {
            filtered = filtered.filter(p => p.categoryId === categoryId || p.id === categoryId);
          }
          if (fabric) filtered = filtered.filter(p => p.fabric === fabric);
          if (minPrice) filtered = filtered.filter(p => p.price >= minPrice);
          if (maxPrice) filtered = filtered.filter(p => p.price <= maxPrice);

          state.products = filtered;
          state.pagination = {
            page: 0,
            size: 12,
            totalElements: filtered.length,
            totalPages: 1,
            last: true,
          };
        }
      })
      .addCase(filterProducts.rejected, (state, action) => {
        state.loading = false;
        const { minPrice, maxPrice, fabric, categoryId, categoryName } = action.meta.arg || {};
        let filtered = MOCK_PRODUCTS;
        if (categoryName) {
          filtered = filtered.filter(p => p.categoryName?.toLowerCase().includes(categoryName.toLowerCase()));
        } else if (categoryId) {
          filtered = filtered.filter(p => p.categoryId === categoryId || p.id === categoryId);
        }
        if (fabric) filtered = filtered.filter(p => p.fabric === fabric);
        if (minPrice) filtered = filtered.filter(p => p.price >= minPrice);
        if (maxPrice) filtered = filtered.filter(p => p.price <= maxPrice);

        state.products = filtered;
        state.pagination = {
          page: 0,
          size: 12,
          totalElements: filtered.length,
          totalPages: 1,
          last: true,
        };
        state.error = null;
      });
  },
});

export const { setFilters, clearFilters, setSearchQuery, clearSelectedProduct, clearError } = productSlice.actions;
export default productSlice.reducer;
